using PathEcho.Core.Update;

var channel=args[0];var candidateRoot=Path.GetFullPath(args[1]);var previous=Path.GetFullPath(args[2]);var expectedVersion=args[3];
if(channel is not ("Lite" or "Full") || !Version.TryParse(expectedVersion,out _))throw new ArgumentException("Invalid channel or expected version");
var root=Path.GetFullPath("temp/upgrade-tests/e2e-"+channel+"-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
var manifestPath=Path.Combine(candidateRoot,"update-"+channel.ToLowerInvariant()+".json");
var candidate=Path.Combine(candidateRoot,"PathEcho-"+expectedVersion+"-"+channel+".zip");
using var http=new HttpClient(new CandidateTransport(manifestPath,candidate));
var signed=await new UpdateManifestClient(http).FetchAsync(new Uri("https://github.com/Kratosmax/PathEcho/releases/latest/download/update-"+channel.ToLowerInvariant()+".json"),channel);
if(signed.Version!=expectedVersion)throw new Exception("Wrong signed candidate version");
var downloaded=Path.Combine(root,"downloaded.zip");await new UpdatePackageDownloader(http).DownloadAsync(new Uri(signed.DownloadUrl),downloaded,signed.Sha256,signed.PackageSize);
UpdatePackageValidator.Validate(downloaded,channel,signed.Version);
var target=Path.Combine(root,"installation");CopyTree(previous,target);
await File.WriteAllTextAsync(Path.Combine(target,"unins000.dat"),"test uninstall sentinel");
var launcher=Path.Combine(root,"launcher");Directory.CreateDirectory(launcher);foreach(var file in Directory.GetFiles(previous).Where(p=>Path.GetFileName(p).StartsWith("PathEcho.Updater")||Path.GetFileName(p).StartsWith("PathEcho.Core")))File.Copy(file,Path.Combine(launcher,Path.GetFileName(file)));
var resultRoot=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"PathEcho","Update");Directory.CreateDirectory(resultRoot);var result=Path.Combine(resultRoot,"result-upgrade-verification-"+Guid.NewGuid().ToString("N")+".json");var ready=result+".handoff-ready";
var oldStart=new ProcessStartInfo(Path.Combine(target,"PathEcho.exe")){UseShellExecute=false};oldStart.ArgumentList.Add("--preview");oldStart.ArgumentList.Add("--preview-seed");using var old=Process.Start(oldStart)!;await Task.Delay(600);if(old.HasExited)throw new Exception("Original client failed to start");
var start=new ProcessStartInfo(Path.Combine(launcher,"PathEcho.Updater.exe")){UseShellExecute=false,WorkingDirectory=launcher,RedirectStandardError=true,RedirectStandardOutput=true};foreach(var arg in new[]{"--package",downloaded,"--manifest",manifestPath,"--channel",channel,"--target",target,"--pid",old.Id.ToString(),"--process-start-filetime",old.StartTime.ToUniversalTime().ToFileTimeUtc().ToString(),"--result",result,"--handoff-ready",ready,"--preview-restart","true","--log-directory",Path.Combine(root,"logs")})start.ArgumentList.Add(arg);
start.Environment["PATHECHO_CAPTURE_PATH"]=Path.Combine(root,"updated-preview.png");start.Environment["PATHECHO_CAPTURE_VIEW"]="Settings";
using var updater=Process.Start(start)!;var error=updater.StandardError.ReadToEndAsync();var output=updater.StandardOutput.ReadToEndAsync();var deadline=DateTime.UtcNow.AddSeconds(12);while(!File.Exists(ready)){if(updater.HasExited)throw new Exception("Old updater exited before handshake: "+await error);if(DateTime.UtcNow>deadline)throw new TimeoutException("No handoff");await Task.Delay(100);}old.Kill();await old.WaitForExitAsync();await updater.WaitForExitAsync().WaitAsync(TimeSpan.FromSeconds(40));if(updater.ExitCode!=0)throw new Exception("Old updater failed: "+await error);
var newProcesses=Process.GetProcessesByName("PathEcho").Where(p=>{try{return p.MainModule?.FileName==Path.Combine(target,"PathEcho.exe");}catch{return false;}}).ToArray();
foreach(var p in newProcesses){var dialogDeadline=DateTime.UtcNow.AddSeconds(10);while(!p.HasExited&&DateTime.UtcNow<dialogDeadline){Native.EnumWindows((hwnd,_)=>{Native.GetWindowThreadProcessId(hwnd,out var owner);if(owner!=(uint)p.Id)return true;var className=new StringBuilder(256);Native.GetClassName(hwnd,className,className.Capacity);if(className.ToString()=="#32770")Native.PostMessage(hwnd,0x0111,new IntPtr(1),IntPtr.Zero);return true;},IntPtr.Zero);await Task.Delay(100);}if(!p.HasExited){p.Kill();await p.WaitForExitAsync();}p.Dispose();}
var captureStart=new ProcessStartInfo(Path.Combine(target,"PathEcho.exe")){UseShellExecute=false};captureStart.ArgumentList.Add("--preview");captureStart.ArgumentList.Add("--preview-seed");captureStart.Environment["PATHECHO_CAPTURE_PATH"]=Path.Combine(root,"updated-preview.png");captureStart.Environment["PATHECHO_CAPTURE_VIEW"]="Settings";using(var capture=Process.Start(captureStart)!){await capture.WaitForExitAsync().WaitAsync(TimeSpan.FromSeconds(15));if(capture.ExitCode!=0)throw new Exception("Installed client capture failed");}
if(!File.Exists(Path.Combine(root,"updated-preview.png")))throw new Exception("New client screenshot missing");if(!File.Exists(Path.Combine(target,"unins000.dat")))throw new Exception("Uninstaller sentinel lost");if(File.ReadAllText(Path.Combine(target,"version.txt")).Trim()!=expectedVersion)throw new Exception("Installed wrong version");if(Directory.GetDirectories(root,".pathecho-*").Length!=0)throw new Exception("Transaction directories left behind");
var report=new{channel,oldCoreVersion=typeof(UpdateManifestClient).Assembly.GetName().Version?.ToString(),oldClient="original published binaries from verified previous package",manifestVerified=true,packageHashAndPrecheck=true,transport="in-process non-seek stream carrying authentic signed candidate",originalUpdaterHandoff=true,oldClientExit="controlled owned preview process exit",newClientVersion=expectedVersion,newPreviewReady=true,restartedPreviewShutdown="controlled after ready",installedClientCapture="separate explicit isolated preview run",uninstallerPreserved=true,transactionDirectories=0,root};var json=JsonSerializer.Serialize(report,new JsonSerializerOptions{WriteIndented=true});await File.WriteAllTextAsync(Path.Combine(root,"report.json"),json);Console.WriteLine(json);foreach(var file in new[]{result,result+".handoff-ready",result+".ready"})if(File.Exists(file))File.Delete(file);
static void CopyTree(string source,string dest){Directory.CreateDirectory(dest);foreach(var d in Directory.GetDirectories(source))CopyTree(d,Path.Combine(dest,Path.GetFileName(d)));foreach(var f in Directory.GetFiles(source))File.Copy(f,Path.Combine(dest,Path.GetFileName(f)));}
sealed class CandidateTransport(string manifest,string package):HttpMessageHandler{protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct){var file=request.RequestUri!.AbsolutePath.EndsWith(".json")?manifest:package;return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){RequestMessage=request,Content=new StreamContent(new NonSeek(File.OpenRead(file)))});}}
sealed class NonSeek(Stream inner):Stream{public override bool CanRead=>true;public override bool CanSeek=>false;public override bool CanWrite=>false;public override long Length=>throw new NotSupportedException();public override long Position{get=>throw new NotSupportedException();set=>throw new NotSupportedException();}public override int Read(byte[] b,int o,int c)=>inner.Read(b,o,c);public override ValueTask<int> ReadAsync(Memory<byte>b,CancellationToken t=default)=>inner.ReadAsync(b,t);public override void Flush(){}public override long Seek(long o,SeekOrigin s)=>throw new NotSupportedException();public override void SetLength(long l)=>throw new NotSupportedException();public override void Write(byte[]b,int o,int c)=>throw new NotSupportedException();protected override void Dispose(bool disposing){if(disposing)inner.Dispose();base.Dispose(disposing);}}

static class Native{internal delegate bool EnumProc(IntPtr hwnd,IntPtr lParam);[DllImport("user32.dll")] [return:MarshalAs(UnmanagedType.Bool)] internal static extern bool EnumWindows(EnumProc callback,IntPtr lParam);[DllImport("user32.dll")]internal static extern uint GetWindowThreadProcessId(IntPtr hwnd,out uint pid);[DllImport("user32.dll",CharSet=CharSet.Unicode)]internal static extern int GetClassName(IntPtr hwnd,StringBuilder name,int max);[DllImport("user32.dll")] [return:MarshalAs(UnmanagedType.Bool)]internal static extern bool PostMessage(IntPtr hwnd,uint msg,IntPtr wParam,IntPtr lParam);}
